# Use backtracking with constraint propagation for 3-coloring
edges = [
    (0,5), (0,12), (0,14), (1,3), (1,6), (1,12), (1,14), (1,23), (2,19), (2,25),
    (3,14), (3,18), (4,21), (4,22), (6,11), (6,26), (7,9), (7,24), (8,12), (8,25),
    (9,11), (9,13), (9,19), (9,20), (9,31), (10,18), (10,19), (11,21), (12,16),
    (12,18), (12,28), (13,14), (13,24), (14,15), (14,18), (14,24), (15,16), (15,19),
    (17,22), (18,24), (19,27), (20,23), (21,27), (22,27), (23,31), (24,25), (25,31),
    (27,29), (27,30), (28,30)
]

n = 32
adj = [[] for _ in range(n)]
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Use simple backtracking with MRV heuristic
import sys
sys.setrecursionlimit(10000)

colors = [-1] * n

def is_valid(v, c):
    for nb in adj[v]:
        if colors[nb] == c:
            return False
    return True

def backtrack():
    # Find uncolored vertex with most constraints (MRV)
    uncolored = [i for i in range(n) if colors[i] == -1]
    if not uncolored:
        return True

    # MRV: pick vertex with fewest available colors
    best_v = None
    best_avail = 4
    for v in uncolored:
        used = {colors[nb] for nb in adj[v] if colors[nb] != -1}
        avail = 3 - len(used)
        if avail < best_avail:
            best_avail = avail
            best_v = v
            if avail == 0:
                return False
            if avail == 1:
                break

    v = best_v
    used = {colors[nb] for nb in adj[v] if colors[nb] != -1}
    for c in range(3):
        if c not in used:
            colors[v] = c
            if backtrack():
                return True
            colors[v] = -1
    return False

if backtrack():
    print("SATISFIABLE")
    print(colors)
else:
    print("UNSATISFIABLE")
